const resp = $('List Bot Channels').first().json;
const body = (resp && resp.body !== undefined) ? resp.body : resp;
let channels = (body && body.data) || [];
if (!Array.isArray(channels)) channels = [];
const cursors = {};
for (const row of $('Read Cursors').all().map(i => i.json)) { if (row && row.channel_id) cursors[String(row.channel_id)] = row.last_seen_ms; }
const out = [];
for (const c of channels) {
  const id = String((c && c.id) || '');
  if (!id) continue;
  const cur = (id in cursors) ? Number(cursors[id]) : null;
  out.push({ json: { channel_id: id, last_seen_ms: cur } });
}
return out;

const AGENT_ID = '99811284';
const plans = $('Plan Per Channel').all().map(i => i.json);
const resp = $('Fetch Channel Messages').all().map(i => i.json);
const out = [];
for (let i = 0; i < plans.length; i++) {
  const ch = plans[i] || {};
  const channel_id = String(ch.channel_id || '');
  if (!channel_id) continue;
  const prevCursor = (ch.last_seen_ms === null || ch.last_seen_ms === undefined) ? null : Number(ch.last_seen_ms);
  const r = resp[i] || {};
  const body = (r && r.body !== undefined) ? r.body : r;
  let msgs = (body && body.data) || [];
  if (!Array.isArray(msgs)) msgs = [];
  let maxDate = prevCursor || 0;
  let newestId = '';
  for (const m of msgs) { const d = Number((m && m.date) || 0); if (d > maxDate) { maxDate = d; newestId = String((m && m.id) || ''); } }
  if (prevCursor === null) {
    out.push({ json: { _kind: 'cursor', channel_id, last_seen_ms: maxDate, last_message_id: newestId } });
    continue;
  }
  for (const m of msgs) {
    const d = Number((m && m.date) || 0);
    if (d <= prevCursor) continue;
    if (String((m && m.user_id) || '') === AGENT_ID) continue;
    out.push({ json: { _kind: 'candidate', channel_id, message_id: String((m && m.id) || ''), user_id: String((m && m.user_id) || ''), content: String((m && m.content) || ''), date: d } });
  }
  out.push({ json: { _kind: 'cursor', channel_id, last_seen_ms: Math.max(prevCursor, maxDate), last_message_id: newestId || ch.last_message_id || '' } });
}
return out;

const AGENT_ID = '99811284';
const cands = $('Process Channels').all().map(i => i.json).filter(j => j && j._kind === 'candidate');
const tags = $('Fetch Tagged Users').all().map(i => i.json);
const out = [];
for (let i = 0; i < cands.length; i++) {
  const t = tags[i] || {};
  const body = (t && t.body !== undefined) ? t.body : t;
  let arr = (body && body.data) || [];
  if (!Array.isArray(arr)) arr = [];
  let mentioned = false;
  for (const u of arr) {
    if (u == null) continue;
    let id;
    if (typeof u === 'object') { id = (u.id != null) ? u.id : ((u.user_id != null) ? u.user_id : (u.user && u.user.id)); }
    else { id = u; }
    if (String(id) === AGENT_ID) { mentioned = true; break; }
  }
  if (mentioned) out.push({ json: cands[i] });
}
return out;

const c = $json;
const job = {
  task_id: null,
  caller_user_id: String(c.user_id || ''),
  impact: 'Średni',
  invocation_type: 'explicit_mention',
  enqueued_at: new Date().toISOString(),
  payload: {
    reviewer_user_id: String(c.user_id || ''),
    caller_username: '',
    triggered_by: 'explicit_mention',
    triggering_comment_id: '',
    triggering_comment_text: String(c.content || ''),
    surface: 'chat',
    surface_ref: { channel_id: String(c.channel_id || ''), message_id: String(c.message_id || '') }
  }
};
return { json: Object.assign({}, c, { job }) };

