insert into chat_poll_cursor (channel_id, last_seen_ms, last_message_id, updated_at)
values ($1, $2, $3, now())
on conflict (channel_id) do update set last_seen_ms = greatest(chat_poll_cursor.last_seen_ms, excluded.last_seen_ms), last_message_id = excluded.last_message_id, updated_at = now();
